text:
one thing i love about rust&#x27;s macros is that you can accomplish this without needing a separate file type or inventing syntax<p><pre><code>   #[component]
   pub fn HomePage(user: Option&lt;User&gt;) -&gt; Element {
      rsx! {
         Layout { 
            title: &quot;Home&quot;,
            if let Some(u) = user {
               h1 { &quot;Welcome back, {u.name}!&quot; }
               a { href: &quot;&#x2F;users&#x2F;{u.id}&quot;, &quot;Your profile&quot; }
            } else {
               h1 { &quot;Welcome, guest!&quot; }
               a { href: &quot;&#x2F;login&quot;, &quot;Log in&quot; }
            }
         }
      }
   }</code></pre>
